rep('docs/api.md', [
 ("""```ts
import { fetchEventSource } from '@microsoft/fetch-event-source'

await fetchEventSource(`/api/v1/runs/${runId}/stream?after_seq=${lastSeq}`, {
  method: 'GET',
  headers: { Authorization: `Bearer ${token}`, Accept: 'text/event-stream' },
  signal: controller.signal,
  openWhenHidden: true,
  onmessage(ev) {
    if (!ev.event || ev.event === 'ping') return
    const seq = Number(ev.id)
    if (seq <= lastSeq) return // 去重，只前进
    lastSeq = seq
    handleEvent(ev.event, JSON.parse(ev.data))
  },
})
```""",
  """```ts
import { fetchEventSource } from '@microsoft/fetch-event-source'

const controller = new AbortController()
let lastSeq = 0

await fetchEventSource(`/api/v1/runs/${runId}/stream?after_seq=${lastSeq}`, {
  method: 'GET',
  headers: { Authorization: `Bearer ${token}`, Accept: 'text/event-stream' },
  signal: controller.signal,
  openWhenHidden: true,
  onmessage(ev) {
    if (!ev.event || ev.event === 'ping') return
    const seq = Number(ev.id)
    if (seq <= lastSeq) return // 去重，只前进
    lastSeq = seq
    handleEvent(ev.event, JSON.parse(ev.data))
    if (isTerminal(ev.event)) controller.abort() // message.done 等终态：停止，不再重连
  },
  onclose() {
    // 服务端终态关闭：不重试；需要时由调用方触发 refreshHistory()
    controller.abort()
  },
  onerror(err) {
    // 400 replay_too_large / 401 / 404：不重试，转轮询或刷新
    // 网络错误：交给调用方有限重试
    throw err
  },
})
```"""),
 ('> 步骤类型五类：`knowledge_search`、`tool`、`a2a`、`approval`、`answer`；不做 DAG/并行/外部引擎。',
  '> 步骤类型五类：`knowledge_search`、`tool`、`a2a`、`approval`、`answer`；不做 DAG/并行/外部引擎。\n>\n> **待冻结**：五类步骤的参数 schema 尚未定义，以上为前端表单草案；M9 handoff 需同时冻结 `steps` JSONB 结构，并显式把 `capabilities.workflows` 置 `true`（当前恒 `false`）。'),
])
rep('docs/pages.md', [
 ('| 编辑器 | 线性步骤列表（增删/上移下移）；五类步骤参数表单：',
  '| 编辑器 | 线性步骤列表（增删/上移下移）；五类步骤参数表单（**草案，待 M9 handoff 冻结 `steps` schema**）：'),
])
print('ok')
EOF", "description": "补续流终止控制与 M9 schema 待冻结说明"}

